def lowercase_existing_emails(apps, schema_editor):
    """Normaliza a minúsculas los emails ya existentes antes de crear el índice
    funcional case-insensitive, para dejar la data consistente con
    CustomUser.save() y para que AddConstraint no falle.

    Si ya existieran dos filas cuyo email difiere solo en mayúsculas/minúsculas,
    el índice CI es imposible: abortamos con un mensaje accionable (qué emails
    colisionan) en vez de dejar que el deploy reciba un IntegrityError genérico
    sin diagnóstico.
    """
    CustomUser = apps.get_model('users', 'CustomUser')

    colisiones = (
        CustomUser.objects.annotate(email_ci=Lower('email'))
        .values('email_ci')
        .annotate(n=Count('id'))
        .filter(n__gt=1)
        .order_by('email_ci')
    )
    conflictivos = [f"{c['email_ci']} (x{c['n']})" for c in colisiones]
    if conflictivos:
        raise RuntimeError(
            "No se puede crear el índice único case-insensitive de email "
            "(user_email_ci_unique): hay emails duplicados que difieren solo en "
            "mayúsculas/minúsculas. Resolvelos (renombrá o dá de baja las cuentas "
            "sobrantes) y volvé a correr la migración. Emails en conflicto: "
            + ", ".join(conflictivos)
        )

    for user in CustomUser.objects.exclude(email__isnull=True):
        if user.email and user.email != user.email.lower():
            user.email = user.email.lower()
            user.save(update_fields=['email'])


